class Stock {
  #levels = new Map();
  set(sku, qty) { this.#levels.set(sku, qty); }
  restock(sku, qty) { this.set(sku, this.level(sku) + qty); }
  level(sku) { return this.#levels.get(sku) ?? 0; }
}

class CountingStock {
  #stock;
  #changes = 0;
  constructor(stock) { this.#stock = stock; }
  set(sku, qty) { this.#changes += 1; this.#stock.set(sku, qty); }
  restock(sku, qty) { this.#changes += 1; this.#stock.restock(sku, qty); }
  level(sku) { return this.#stock.level(sku); }
  get changes() { return this.#changes; }
}

const stock = new CountingStock(new Stock());
stock.set("RICE", 10);
stock.restock("RICE", 5);
console.log(stock.changes, stock.level("RICE"));

