let calls = 0;
const gateway = {
  async charge(amountKobo, reference) {
    calls += 1;
    return `paid ${reference}`;
  },
};

function withLimit(gateway, maxKobo) {
  return {
    async charge(amountKobo, reference) {
      if (amountKobo > maxKobo) throw new Error("over limit");
      return gateway.charge(amountKobo, reference);
    },
  };
}

const limited = withLimit(gateway, 1000000);
console.log(await limited.charge(500000, "ORD-1"));
try {
  await limited.charge(2000000, "ORD-2");
} catch (error) {
  console.log(error.message);
}
console.log(calls);

